                        }
                    }
                    if ($found == 0) {
                        my $n = readlink($f);
                        if (index($n,"/") == -1) {
                            my $dirname = dirname($f);
                            $n = "$dirname/$n"; #TODO: what if relative?
                        }
                        my %vsaaa = ("type" => "dir-link", "source" => $n);
                        my %st1 = ($x => \%vsaaa );
                        push(@{$last_files_block}, \%st1);
                    }
                }
                last;
            }
            my $found = 0;
            foreach my $v (@{$last_files_block}) {
                if (defined($v->{$x})) {
                    $last_files_block = $v->{$x}{"files"};
                    $counter += 1;
                    $found = 1;
                    last;
                }
            }
            if ($found == 0) {
                my %vsaaa = ("type" => "dir", "files" => [] );
                my %st1 = ($x => \%vsaaa );
                push(@{$last_files_block}, \%st1);
                $last_files_block = $vsaaa{"files"};
                $counter += 1;
            }
        }
    } elsif (-f $f) {
        print($f, " is a file\n");
        my @a = split("/",$f);
        my $result;
        my $counter = 0; 
        my $last_files_block = $st{"/"}{"files"};
        while (1) {
            unless ($counter < scalar(@a)) {
                last;
            }
            my $x = $a[$counter];
            if ($x eq '') {
                $counter += 1;
                next;
            }
            if ($counter + 1 == scalar(@a)) {
                my $found = 0;
                foreach my $v (@{$last_files_block}) {
                    if (defined($v->{$x})) {
                        $found = 1;
                        last;
                    }
                }
                if ($found == 0) {
                    my %vsaaa = ("type" => "file");
                    my %st1 = ($x => \%vsaaa );
                    push(@{$last_files_block}, \%st1);
                }
                last;
            }
            my $found = 0;
            foreach my $v (@{$last_files_block}) {
                if (defined($v->{$x})) {
                    $last_files_block = $v->{$x}{"files"};
                    $counter += 1;
                    $found = 1;
                    last;
                }
            }
            if ($found == 0) {
                my %vsaaa = ("type" => "dir", "files" => [] );
                my %st1 = ($x => \%vsaaa );
                push(@{$last_files_block}, \%st1);
                $last_files_block = $vsaaa{"files"};
                $counter += 1;
            }
        }
    } elsif (-d $f) {
        print($f, " is a dir\n");
        my @a = split("/",$f);
        my $result;
        my $counter = 0; 
        my $last_files_block = $st{"/"}{"files"};
            while (1) {
            unless ($counter < scalar(@a)) {
                last;
            }
            my $x = $a[$counter];
            if ($x eq '') {
                $counter += 1;
                next;
            }
            my $found = 0;
            my $found_link = 0;
            foreach my $v (@{$last_files_block}) {
                if (defined($v->{$x})) {
