            }
            if ($found == 0) {
                my %vsaaa = ("type" => "dir", "files" => [] );
                my %st1 = ($x => \%vsaaa );
                push(@{$last_files_block}, \%st1);
                $last_files_block = $vsaaa{"files"};
                $counter += 1;
            }
        }
    } else {
            #TODO: When can it happen other than path does not exist or permission denied? 
            print($f, " is a special\n");
    }
}
</code>
